var IncidentUtils = Class.create();
IncidentUtils.prototype = {
    initialize: function() {
        this.priorityThreshold = 2; // 1 = Critical, 2 = High
    },

    isHighPriority: function(gr) {
        return parseInt(gr.getValue('priority'), 10) <= this.priorityThreshold;
    },

    type: 'IncidentUtils'
};

